% The COBRAToolbox: testSlvrCumomer.m
%
% Purpose:
%     - slvrCumomer is the cumomer solver generated by generateIsotopomerSolver (Perl script
%       generatorCumomer.pl) for the E. coli isotopomer model of testFitC13Data (model.mat, 335
%       reactions). Given a flux vector and the glucose label input as a cumomer vector of 64
%       entries, it solves eleven levels of sparse linear systems and returns the isotopomer
%       distribution vectors (IDVs) of 17 amino acids. The test uses the fixtures of this folder:
%       the steady-state flux vector v0 (point.mat) and the label input expdata.input of
%       expdata.mat, and checks
%         * the 17 output fields and the length of each IDV (2^n for an amino acid of n carbons:
%           Ala 3, Asn 4, Asp 4, Gln 5, Glu 5, Gly 2, His 6, Ile 6, Leu 6, Lys 6, Met 5, Phe 9,
%           Pro 5, Ser 3, Thr 4, Tyr 9, Val 5), that each IDV sums to 1 and is nonnegative;
%         * that an unlabelled glucose input gives the IDV [1 0 ... 0] (all molecules unlabelled)
%           for every amino acid (no 13C enters the network: independent derivation);
%         * that the mass distributions of the 36 fragments computed from these IDVs (idv2mdv)
%           agree with the elementary metabolite unit (EMU) solver slvrEMU_fast generated from the
%           same model: the two solvers use different algorithms (cumomers of whole molecules
%           against EMUs of fragments), so their agreement is an independent check of the values.
%
% Function under test:
%     src/dataIntegration/fluxomics/c13solver/slvrCumomer.m
%
% Tier (Constitution III-Coverage):
%     Tier 3 - the function under test is written in the test by generateIsotopomerSolver, whose
%     flux variability step needs an LP solver and whose scripts need Perl (declared with
%     prepareTest). The function itself uses no solver (the linear systems are solved by
%     solveLin with backslash) and no genome-scale model: the flux vector and label input are
%     the small fixtures point.mat and expdata.mat of this folder. The function is about 82,600
%     lines of generated straight-line code; one call takes about 1.3 s and 1.2 GB of memory.
%
% Coverage exemptions:
%     None. Every executable line is reached below (the function is straight-line code).
%
% Known defects documented (NOT tested, NOT fixed here):
%     None found.
%
% Authors:
%     - Generated for feature 20261113-142115-test-backfill-tiers, 2026-11-15.
%     - Generates the solver files it tests itself, as the CI run has none (T035), 2026-11-20.

% save the current path
currentDir = pwd;

% initialize the test
fileDir = fileparts(which('testSlvrCumomer'));
cd(fileDir);

% declare the requirements of this test: an LP solver and Perl, both used only to generate
% the solver files below
solvers = prepareTest('needsLP', true, 'requiredSoftwares', {'perl'});

% the solver files (slvr*.m, convertCarbonInput.m) are written by generateIsotopomerSolver for
% a given model and are not kept in the repository (.gitignore); generate them here for
% model.mat of this folder, as testFitC13Data does. Solver files present now (perhaps generated
% for another model) are copied to a temporary folder and put back at the end
c13Dir = fileparts(which('generateIsotopomerSolver'));
c13Files = {'IsotopomerModel.txt'; 'convertCarbonInput.m'; 'slvrCumomer.m'; 'slvrCumomer_fast.m'; ...
    'slvrEMU.m'; 'slvrEMU_fast.m'};
c13Existed = cellfun(@(f) exist(fullfile(c13Dir, f), 'file') == 2, c13Files);
c13Backup = tempname;
mkdir(c13Backup);
for k = find(c13Existed)'
    copyfile(fullfile(c13Dir, c13Files{k}), c13Backup);
end
changeCobraSolver(solvers.LP{1}, 'LP', 0);
c13Fixtures = load('model.mat', 'model');
c13Fixtures.expdata = getfield(load('expdata.mat', 'expdata'), 'expdata');
% true: leave out the reactions that carry no flux in any steady state (flux variability), as
% testFitC13Data does
generateIsotopomerSolver(c13Fixtures.model, 'xglcDe', c13Fixtures.expdata, true);
clear c13Fixtures
% make MATLAB read the new files, not versions of them it may hold in memory
rehash;
clear convertCarbonInput slvrCumomer slvrCumomer_fast slvrEMU slvrEMU_fast

% solveLin (called by the function) turns the warning MATLAB:nearlySingularMatrix off and does
% not turn it on again; save its state to restore it at the end
nearlySingularState = warning('query', 'MATLAB:nearlySingularMatrix');

% cdv2idv (called by the function) and idv2mdv (used below) cache matrices in global
% variables; note the globals that exist now to remove the new ones at the end
globalsBefore = who('global');

% fixtures of this folder (shared with testFitC13Data): the flux vector v0 of model.mat and
% the glucose label input expdata.input (cumomer vector of the 6 glucose carbons)
load('point.mat', 'v0');
load('expdata.mat', 'expdata');

% IDV entries are fractions obtained by sparse linear solves and the transformation cdv2idv;
% observed rounding is below 1e-15 for the sums and 3e-12 between the two solvers, so 1e-10
% separates rounding from a real change
tol = 1e-10;

%% output fields, IDV lengths, normalisation and nonnegativity

output = slvrCumomer(v0, expdata.input);
expectedNames = {'xalaL'; 'xasnL'; 'xaspL'; 'xglnL'; 'xgluL'; 'xgly'; 'xhisL'; 'xileL'; ...
    'xleuL'; 'xlysL'; 'xmetL'; 'xpheL'; 'xproL'; 'xserL'; 'xthrL'; 'xtyrL'; 'xvalL'};
% number of carbon atoms of each amino acid, in the order of expectedNames
carbonCount = [3; 4; 4; 5; 5; 2; 6; 6; 6; 6; 5; 9; 5; 3; 4; 9; 5];
assert(isequal(fieldnames(output), expectedNames));
for k = 1:numel(expectedNames)
    idv = output.(expectedNames{k});
    % one entry per isotopomer: 2^n labelling patterns of n carbons
    assert(iscolumn(idv) && numel(idv) == 2^carbonCount(k));
    % an isotopomer distribution sums to one and has no negative fraction
    assert(abs(sum(idv) - 1) < tol);
    assert(all(idv > -tol));
end

%% an unlabelled glucose input leaves every amino acid unlabelled

% all glucose molecules are the isotopomer 000000; its cumomer vector is idv2cdv(6) * e1
unlabelledIdv = zeros(64, 1);
unlabelledIdv(1) = 1;
unlabelledOutput = slvrCumomer(v0, idv2cdv(6) * unlabelledIdv);
for k = 1:numel(expectedNames)
    idv = unlabelledOutput.(expectedNames{k});
    expectedIdv = [1; zeros(numel(idv) - 1, 1)];
    assert(max(abs(idv - expectedIdv)) < tol);
end
clear unlabelledOutput

%% fragment mass distributions agree with the EMU solver of the same model

% slvrEMU_fast takes the label input as mass distributions of glucose fragments and returns
% the mass distribution of each measured fragment; the fragment name ends with one digit per
% carbon of the amino acid (1 = carbon in the fragment), which is the fragment argument of
% idv2mdv
emuOutput = slvrEMU_fast(v0, convertCarbonInput(expdata.input));
fragmentNames = fieldnames(emuOutput);
assert(numel(fragmentNames) == 36);
for k = 1:numel(fragmentNames)
    fragmentName = fragmentNames{k};
    carbonPattern = regexp(fragmentName, '[01]+$', 'match', 'once');
    aminoAcid = fragmentName(1:end - numel(carbonPattern));
    fragment = double(carbonPattern' == '1');
    fragmentMdv = idv2mdv(numel(fragment), fragment) * output.(aminoAcid);
    assert(max(abs(fragmentMdv - emuOutput.(fragmentName))) < tol);
end

% restore the warning state changed by solveLin
warning(nearlySingularState);

% remove the global caches created by cdv2idv and idv2mdv
newGlobals = setdiff(who('global'), globalsBefore);
for k = 1:numel(newGlobals)
    clearvars('-global', newGlobals{k});
end

% put back the solver files present before the test and remove the ones it generated
for k = 1:numel(c13Files)
    if c13Existed(k)
        copyfile(fullfile(c13Backup, c13Files{k}), c13Dir);
    elseif exist(fullfile(c13Dir, c13Files{k}), 'file') == 2
        delete(fullfile(c13Dir, c13Files{k}));
    end
end
rmdir(c13Backup, 's');
rehash;
clear convertCarbonInput slvrCumomer slvrCumomer_fast slvrEMU slvrEMU_fast

% change the directory
cd(currentDir)
